class FlowExample { public: int status; bool valid; bool done; void prepare() { this->status = 1; } void validate() { this->valid = this->status == 1; } void commit() { this->done = this->valid; } void ok1() { prepare(); validate(); commit(); } void ok2() { prepare(); validate(); commit(); } void ok3() { prepare(); validate(); commit(); } void ok4() { prepare(); validate(); commit(); } void drift() { validate(); prepare(); commit(); } };
